def read(path: str) -> str:
    return (ROOT / path).read_text(encoding="utf-8")


def write(path: str, content: str) -> None:
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding="utf-8", newline="\n")


def main() -> int:
    for action in ACTIONS:
        kind = action[0]
        if kind == "create":
            _, path, content = action
            target = ROOT / path
            if target.exists():
                raise RuntimeError(f"create target already exists: {path}")
            write(path, content)
        elif kind == "replace":
            _, path, old, new = action
            source = read(path)
            count = source.count(old)
            if count != 1:
                raise RuntimeError(
                    f"{path}: replacement target count={count}; expected 1"
                )
            write(path, source.replace(old, new, 1))
        elif kind == "block":
            _, path, start_marker, end_marker, replacement = action
            source = read(path)
            start = source.find(start_marker)
            if start < 0:
                raise RuntimeError(f"{path}: block start not found: {start_marker!r}")
            end = source.find(end_marker, start + len(start_marker))
            if end < 0:
                raise RuntimeError(f"{path}: block end not found: {end_marker!r}")
            if source.find(start_marker, start + 1) >= 0:
                raise RuntimeError(f"{path}: block start is not unique")
            write(path, source[:start] + replacement + source[end:])
        elif kind == "delete":
            _, path = action
            target = ROOT / path
            if not target.is_file():
                raise RuntimeError(f"delete target is missing: {path}")
            target.unlink()
        else:
            raise RuntimeError(f"unknown action: {kind}")
    print("AUTHENTIC_TW_REPAIR_PATCH_APPLIED")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
